        bool RecipeAllowed(string id){if(IndustrialCatalog.RetiredConstructionRecipe(id))return false;if(uiMode!="recipes")return true;var machine=Authority.World.Machine(contextTarget);return machine!=null&&IndustrialCatalog.Supports(machine.definition,id);}
        void BuildRecipeGrid(){
            if(browserGrid==null)return;browserGrid.Clear();recipeButtons.Clear();string search=recipeSearch?.value?.Trim()??"";var stock=uiMode=="recipes"?Authority.World.Machine(contextTarget)?.input:actor.inventory;int matches=0;
