                var tile=UiButton(browserGrid,"",()=>{chosenRecipe=id;BuildRecipeDetails();},"recipe-"+id);tile.AddToClassList("industry-recipe-tile");if(!IndustrialCatalog.Handcraft.Contains(id)&&uiMode!="recipes")tile.AddToClassList("station-recipe");if(id==chosenRecipe)tile.AddToClassList("selected");UiText(tile,Abbreviation(id),"industry-item-mark");UiText(tile,Nice(id),"industry-item-name");UiText(tile,Station(id),"industry-item-requirement");tile.tooltip=Nice(id)+" · "+Station(id);recipeButtons.Add(id,tile);matches++;
