        static string Abbreviation(string id){var words=id.Split('-');string text="";foreach(var word in words)if(word.Length>0&&word!="kit")text+=char.ToUpperInvariant(word[0]);return text.Length>3?text.Substring(0,3):text;}
        void BuildRecipeDetails(){
            refreshIngredients=null;if(details==null)return;details.Clear();craftQuantity=null;foreach(var pair in recipeButtons)pair.Value.EnableInClassList("selected",pair.Key==chosenRecipe);
            if(!IndustrialCatalog.Recipes.TryGetValue(chosenRecipe,out var recipe)||!RecipeAllowed(chosenRecipe)){UiText(details,"Select a recipe to inspect its ingredients and requirements.");return;}
            UiText(details,Nice(recipe.id).ToUpperInvariant(),"industry-title");UiText(details,Category(recipe.id)+" · "+Station(recipe.id),"industry-muted");UiText(details,"OUTPUT  "+CostText(recipe.output));UiText(details,$"TIME  {recipe.ticks*.1f:0.0}s per craft"+(recipe.water>0?$" · WATER {recipe.water}":""));
            UiText(details,IndustrialCatalog.Handcraft.Contains(recipe.id)?"Craft items, drag them into the hotbar and press the slot number to equip. Placeables consume one item.":"Supply ingredients to the placed machine. Its production continues while this menu is closed.");
            var ingredients=UiBox(details,"industry-ingredients");ingredients.name="craft-ingredients";var ingredientRows=new List<Label>();foreach(var input in recipe.input)ingredientRows.Add(UiText(ingredients,""));
            craftQuantity=new IntegerField("Quantity"){value=1,name="craft-quantity"};details.Add(craftQuantity);craftQuantity.style.display=uiMode=="recipes"?DisplayStyle.None:DisplayStyle.Flex;var actions=UiBox(details,"industry-row");UiButton(actions,"−",()=>craftQuantity.value=Math.Max(1,craftQuantity.value-1));UiButton(actions,"+",()=>craftQuantity.value=Math.Min(20,craftQuantity.value+1));UiButton(actions,"MAX",()=>craftQuantity.value=MaxCraft(recipe));
            var craftButton=UiButton(details,"",()=>{if(uiMode=="recipes"){Execute(Command("recipe",to:contextTarget,item:recipe.id));}else Execute(Command("craft",item:recipe.id,count:craftQuantity.value));RefreshToolkitMenu(true);},"craft-submit");craftButton.AddToClassList("industry-primary");
            void UpdateIngredients(){int quantity=Math.Max(1,Math.Min(20,craftQuantity.value));var inventory=uiMode=="recipes"?Authority.World.Machine(contextTarget)?.input:actor.inventory;for(int n=0;n<recipe.input.Length;n++){var input=recipe.input[n];long have=inventory?.Count(input.item)??0,need=Authority.World.creativeMode&&uiMode!="recipes"?0:input.count*(uiMode=="recipes"?1:quantity);var row=ingredientRows[n];row.text=$"{Nice(input.item)}    {have:N0} / {need:N0}";row.EnableInClassList("missing",have<need);}
                bool hand=IndustrialCatalog.Handcraft.Contains(recipe.id);craftButton.text=uiMode=="recipes"?"SET PRODUCTION RECIPE":hand?$"CRAFT ×{quantity}":"REQUIRES "+Station(recipe.id).ToUpperInvariant();craftButton.SetEnabled(uiMode=="recipes"?Authority.World.Machine(contextTarget)?.progress==0:hand&&quantity<=MaxCraft(recipe));}
            craftQuantity.RegisterValueChangedCallback(e=>{craftQuantity.SetValueWithoutNotify(Math.Max(1,Math.Min(20,e.newValue)));UpdateIngredients();});refreshIngredients=UpdateIngredients;UpdateIngredients();
            if(!IndustrialCatalog.Handcraft.Contains(recipe.id)&&uiMode!="recipes")UiText(details,"Aim at the required station and press F to manage its inventory and production.","industry-muted");
        }
        int MaxCraft(RecipeDefinition recipe){long max=Math.Min(20,32-actor.craftQueue.Count-(actor.craft==null?0:1));if(!Authority.World.creativeMode)foreach(var input in recipe.input)max=Math.Min(max,actor.inventory.Count(input.item)/input.count);return (int)Math.Max(0,max);}
