        void BuildInteraction(){
            var body=UiBox(menu,"industry-body");contextInventory=new ScrollView();contextInventory.AddToClassList("industry-context-inventory");body.Add(contextInventory);var operations=new ScrollView();operations.AddToClassList("industry-context-actions");body.Add(operations);contextActions=operations;if(Authority.World.inventoryWorkflow)operations.style.width=Length.Percent(30);contextStatus=UiText(operations,"","industry-title");machineProgress=new ProgressBar{title="Production",lowValue=0,highValue=1};operations.Add(machineProgress);
