            if(target.definition=="sluice"&&Authority.World.miningWorkflow){UiText(operations,"Tailings discharge from the front chute. Assign a separate digger/loader to PERIODIC TAILINGS CLEANUP; ore remains in the conveyor output.");UiButton(operations,"SET UP TAILINGS DUMP AWAY FROM SLUICE",()=>EnsureTailingsDump(target),"configure-tailings-dump");UiButton(operations,"RECOVER FRONT TAILINGS · UP TO 100 L",()=>Execute(Command("recover-tailings",target.id,count:Math.Min(100,IndustrialWorld.TailingsCount(target.frontTailings)))));}
            if(target.definition=="pump"){UiButton(operations,"LOCATE NEAREST WATER INTAKE",LocateWater);UiText(operations,"Needs 2 kW and a water pipe to the sluice. Deposit carried Water into MACHINE INPUT, or select a finite WATER deposit within 8 m below. Water flows into the destination reservoir, not the item output.");foreach(var deposit in Authority.World.deposits)if(deposit.resource=="water"&&target.pose.Distance(deposit.pose)<=8){long id=deposit.id;UiButton(operations,"USE WATER INTAKE #"+id+" · "+deposit.remaining.litres+" L",()=>Execute(Command("pump-intake",id,target.id)));}}
