            UiButton(operations,"SWITCH ON / OFF",()=>Execute(Command("toggle",to:target.id)));UiButton(operations,"OPEN / CLOSE SHIELDING",()=>Execute(Command("shield",to:target.id)));
            if(target.definition=="sluice"||IsVehicle(target))UiButton(operations,"LOAD UP TO 100 L PAY DIRT",()=>Execute(Command("bulk-transfer",to:target.id,count:Math.Min(100,actor.inventory.bulk.litres))));
            if(IsVehicle(target)){foreach(var deposit in Authority.World.deposits)if(target.definition=="excavator"&&target.pose.Distance(deposit.pose)<8){var id=deposit.id;UiButton(operations,"EXCAVATE DEPOSIT #"+id,()=>Execute(Command("dig-vehicle",id,target.id,count:Math.Min(200,Authority.World.deposits.Find(x=>x.id==id).remaining.litres))));}foreach(var pile in Authority.World.piles)if(target.pose.Distance(pile.pose)<8){long id=pile.id;UiButton(operations,"DUMP TO PILE #"+id,()=>Execute(Command("bulk-transfer",target.id,id,count:Math.Min(100,target.input.bulk.litres))));UiButton(operations,"SCOOP FROM PILE #"+id,()=>Execute(Command("bulk-transfer",id,target.id,count:Math.Min(100,Authority.World.Pile(id).material.litres))));}}
            UiText(operations,"CONNECTIONS","industry-section");UiText(operations,"Power: solar / wind / generator → battery → machines, or connect a source directly. Batteries charge from unused source power.");UiButton(operations,"USE AS CONNECTION SOURCE",()=>{source=target.id;message="Aim at a destination machine and press F";CloseMenu();});if(target.Definition.PowerProvider)UiButton(operations,"RUN POWER CABLE FROM THIS MACHINE",()=>StartCableTool("power",target.id));if(target.definition=="pump"||target.definition=="water-reservoir")UiButton(operations,"RUN WATER PIPE FROM THIS WATER SOURCE",()=>StartCableTool("water",target.id));if(target.powerSource!=0)UiButton(operations,"REMOVE INCOMING POWER CABLE",()=>Execute(Command("remove-power",to:target.id)));if(target.waterTarget!=0)UiButton(operations,"REMOVE OUTGOING WATER PIPE",()=>Execute(Command("remove-water",to:target.id)));UiText(operations,"Current source: #"+source);var filterField=new TextField("Belt filter (blank = all)"){value=filter};operations.Add(filterField);filterField.RegisterValueChangedCallback(e=>filter=e.newValue);
            UiButton(operations,"CONVEYOR PLANNER FROM THIS OUTPUT",()=>StartCableTool("belt",target.id));UiButton(operations,"CONNECT POWER FROM SOURCE",()=>Execute(Command("power",source,target.id)));UiButton(operations,"CONNECT WATER FROM SOURCE",()=>Execute(Command("water",source,target.id)));UiButton(operations,"TRANSFER 100 L FROM SOURCE",()=>Execute(Command("bulk-transfer",source,target.id,count:100)));
            if(target.definition=="battery")UiButton(operations,"DISCARD STORED BATTERY ENERGY",()=>Execute(Command("drain-energy",to:target.id)));
            UiText(operations,"RECOVERY","industry-section");UiButton(operations,"DISCONNECT POWER AND WATER",()=>Execute(Command("disconnect",to:target.id)));UiButton(operations,"RECOVER RESERVOIR WATER",()=>Execute(Command("drain-water",to:target.id)));foreach(var lane in Authority.World.belts)if(lane.source==target.id||lane.target==target.id){long id=lane.id;UiButton(operations,"RECOVER BELT #"+id+" AND CONTENTS",()=>{Execute(Command("remove-belt",to:id));OpenMenu("machine");});}UiButton(operations,"DISMANTLE EMPTY MACHINE",()=>{Execute(Command("pack",to:target.id));if(Authority.World.Machine(target.id)==null)CloseMenu();}).SetEnabled(!target.integratedLogistics);
        }
        string InventoryKey(Inventory inventory){var text=new System.Text.StringBuilder();foreach(var stack in inventory.items)text.Append(stack.item).Append(':').Append(stack.count).Append(';');return text.Append(inventory.bulk.litres).ToString();}
        void RefreshToolkitMenu(bool force=false){
            if(!MenuOpen||menu==null)return;string inventoryState=InventoryKey(actor.inventory)+Authority.World.creativeMode;if(uiMode=="crafting"||uiMode=="recipes"){
                var machine=uiMode=="recipes"?Authority.World.Machine(contextTarget):null;if(uiMode=="recipes"&&machine==null){CloseMenu();return;}var key=inventoryState+(machine==null?"":InventoryKey(machine.input)+machine.recipe);if(force||lastUiState!=key){lastUiState=key;if(availableOnly?.value==true)BuildRecipeGrid();}refreshIngredients?.Invoke();RefreshQueue(force);
            }else if(uiMode=="construction"){if(!force&&lastUiState!=inventoryState){lastUiState=inventoryState;RebuildMenu();}else lastUiState=inventoryState;}
            else if(contextInventory!=null){
                var machine=Authority.World.Machine(contextTarget);var pile=Authority.World.Pile(contextTarget);if(contextIsPile?pile==null:machine==null){CloseMenu();return;}var pose=contextIsPile?pile.pose:machine.pose;if(actor.pose.Distance(pose)>12){message="Moved out of interaction range";CloseMenu();return;}
                contextStatus.text=contextIsPile?$"{(pile.tailingsPile?"TAILINGS DUMP":"STOCKPILE")} #{pile.id}\n{pile.Volume:N0} L":$"{(machine.displayName??Nice(machine.definition)).ToUpperInvariant()} #{machine.id}\n{(machine==driver?"Driving":machine.status)}\nReservoir {machine.water:N0} L\n · Shielding {machine.integrity:P0}\nPay dirt {machine.input.bulk.litres:N0} L · Tailings cargo {IndustrialWorld.TailingsCount(machine.input):N0} L"+(machine.haul==null?"":$"\nAUTO [{machine.haul.role??"legacy haul"}]: {machine.haul.status}\nSource #{machine.haul.source} → #{machine.haul.destination} · Reserved {machine.haul.reserved} L")+(machine.definition=="sluice"&&Authority.World.miningWorkflow?$"\nFront tailings {IndustrialWorld.TailingsCount(machine.frontTailings):N0}/{IndustrialWorld.FrontTailingsCapacity:N0} L · Dump #{machine.tailingsDump}":"")+(machine.definition=="pump"?$"\nCarried water {machine.input.Count("water"):N0} L · Intake #{machine.waterIntake} · Destination #{machine.waterTarget}":"")+(machine.Definition.PowerProvider?$"\nPower {machine.powerAvailable:0.0} kW"+(machine.definition=="battery"?$" · Stored {machine.energy:0.0}/{MachineDefinition.BatteryCapacity:0} kJ · Charging {machine.chargePower:0.0} kW":""):"");
                machineProgress.style.display=contextIsPile?DisplayStyle.None:DisplayStyle.Flex;if(machine!=null){int ticks=machine.recipe!=null&&IndustrialCatalog.Recipes.TryGetValue(machine.recipe,out var r)?r.ticks:machine.definition=="sluice"?10:100;machineProgress.value=machine.definition=="water-reservoir"?Mathf.Clamp01(machine.water/10000f):machine.definition=="battery"?(float)(machine.energy/MachineDefinition.BatteryCapacity):Mathf.Clamp01(machine.progress/(float)ticks);machineProgress.title=machine.definition=="water-reservoir"?$"Reservoir · {machine.water:N0} / 10,000 L":machine.definition=="battery"?$"Stored energy · {machineProgress.value:P0}":machine.Definition.PowerProvider?$"Available power · {machine.powerAvailable:0.0} kW":Nice(machine.recipe)+$" · {machineProgress.value:P0}";}
                if(Authority.World.inventoryWorkflow&&machine!=null){if(contextInventory.Q("inventory-grid-player-0")==null)world.BuildMachineSlots(contextInventory,machine);return;}string state=inventoryState+(machine==null?pile.revision.ToString():InventoryKey(machine.input)+InventoryKey(machine.output)+actor.wearingProtection);if(force||state!=lastContextState){lastContextState=state;var scroll=contextInventory as ScrollView;Vector2 offset=scroll?.scrollOffset??default;contextInventory.Clear();UiText(contextInventory,"YOUR MATERIALS","industry-section");if(machine!=null)foreach(var stack in actor.inventory.items){if((machine.definition=="water-reservoir"||machine.definition=="sluice")&&stack.item!="water")continue;string item=stack.item;long count=Math.Min(10,stack.count);UiButton(contextInventory,$"{Nice(item)} ×{stack.count:N0}    → "+(item=="water"&&(machine.definition=="water-reservoir"||machine.definition=="sluice")?"Fill reservoir ":"Deposit ")+count,()=>Execute(Command(item=="water"&&(machine.definition=="water-reservoir"||machine.definition=="sluice")?"fill-water":"deposit-item",to:contextTarget,item:item,count:Math.Min(count,actor.inventory.Count(item)))));}else UiText(contextInventory,InventoryText(actor.inventory));
                    if(machine!=null){UiText(contextInventory,"MACHINE INPUT","industry-section");foreach(var stack in machine.input.items){string item=stack.item;long count=Math.Min(10,stack.count);UiButton(contextInventory,$"{Nice(item)} ×{stack.count:N0}    ← Take {count}",()=>Execute(Command("withdraw-input",contextTarget,item:item,count:Math.Min(count,machine.input.Count(item)))));}if(machine.input.bulk.litres>0)UiButton(contextInventory,"RECOVER UP TO 100 L PAY DIRT",()=>Execute(Command("bulk-transfer",contextTarget,count:Math.Min(100,machine.input.bulk.litres))));UiText(contextInventory,"OUTPUT / STORAGE","industry-section");foreach(var stack in machine.Definition.storage?new List<ItemStack>():machine.Export.items){string item=stack.item;long count=Math.Min(10,stack.count);UiButton(contextInventory,$"{Nice(item)} ×{stack.count:N0}    ← Take {count}",()=>Execute(Command("withdraw-item",contextTarget,item:item,count:Math.Min(count,machine.Export.Count(item)))));}}
                    if(actor.inventory.Count("radiation-suit")>0)UiButton(contextInventory,actor.wearingProtection?"REMOVE RADIATION SUIT":"WEAR RADIATION SUIT",()=>Execute(Command("protection")));if(actor.inventory.Count("decontamination-kit")>0)UiButton(contextInventory,"USE DECONTAMINATION KIT",()=>Execute(Command("treat")));if(scroll!=null)scroll.scrollOffset=offset;
                }
