        }
        void RefreshQueue(bool force){
            if(queue==null)return;var jobs=new List<IndustrialCraftJob>();if(actor.craft!=null)jobs.Add(actor.craft);jobs.AddRange(actor.craftQueue);string key=string.Join(",",jobs.ConvertAll(x=>x.id+":"+x.recipe));if(force||key!=lastQueueState){lastQueueState=key;queue.Clear();UiText(queue,"CRAFTING QUEUE  ·  "+jobs.Count+" / 32","industry-section");craftProgress=new ProgressBar{lowValue=0,highValue=1};queue.Add(craftProgress);var jobScroll=new ScrollView(ScrollViewMode.Horizontal);jobScroll.style.height=60;queue.Add(jobScroll);var row=UiBox(jobScroll,"industry-row");foreach(var job in jobs){long id=job.id;UiButton(row,Nice(job.recipe)+"  ×",()=>{Execute(Command("cancel-craft",to:id));RefreshToolkitMenu(true);},"cancel-craft-"+id).tooltip="Cancel this job and recover its ingredients";}if(jobs.Count==0)UiText(row,"Choose a recipe to begin. Survival ingredients are reserved when queued.");}
            if(craftProgress!=null){craftProgress.style.display=actor.craft==null?DisplayStyle.None:DisplayStyle.Flex;if(actor.craft!=null){var recipe=IndustrialCatalog.Recipes[actor.craft.recipe];craftProgress.value=actor.craft.progress/(float)recipe.ticks;craftProgress.title=Nice(recipe.id)+$" · {(recipe.ticks-actor.craft.progress)*.1f:0.0}s remaining";}}
        }
        void FindAimedItem(){
            aimedMachine=null;aimedPile=null;if(!world.IsFirstPerson||MenuOpen||PlacementActive)return;var ray=new Ray(world.View.transform.position,world.View.transform.forward);float best=5;Physics.SyncTransforms();if(Physics.Raycast(ray,out var hit,5,Physics.DefaultRaycastLayers,QueryTriggerInteraction.Ignore))best=hit.distance+.15f;
            foreach(var machine in nearby){if(machine.externalVehicle!=0||actor.pose.Distance(machine.pose)>12)continue;if(machine.definition=="sluice"&&IndustrialWorld.TailingsCount(machine.frontTailings)>0){var point=IndustrialWorld.TailingsPose(machine);float radius=(float)IndustrialWorld.TailingsRadius(IndustrialWorld.TailingsCount(machine.frontTailings));var moundRotation=Quaternion.Inverse(Rotation(point));var moundRay=new Ray(moundRotation*(ray.origin-world.RenderBodyPosition(Body(point))),moundRotation*ray.direction);var moundBounds=new Bounds(Vector3.up*radius*.35f,new Vector3(radius*2,radius*.7f,radius*2));if(moundBounds.IntersectRay(moundRay,out float moundDistance)&&moundDistance>=0&&moundDistance<=best){best=moundDistance;aimedMachine=machine;}}if(machine.integratedLogistics){foreach(var pin in new[]{machine.conveyorInput,machine.conveyorOutput}){var portBounds=new Bounds(world.RenderBodyPosition(Body(pin)),Vector3.one*.7f);if(portBounds.IntersectRay(ray,out float portDistance)&&portDistance>=0&&portDistance<=best){best=portDistance;aimedMachine=machine;}}}var rotation=Quaternion.Inverse(Rotation(machine.pose));var localRay=new Ray(rotation*(ray.origin-world.RenderBodyPosition(Body(machine.pose))),rotation*ray.direction);var prototype=ColonyPrototypeLibrary.Find("machine-"+machine.definition);var bounds=prototype?.Mesh(prototype.id).bounds??new Bounds(Vector3.up*1.5f,new Vector3(2.5f,3,5));bounds.Expand(.15f);if(bounds.IntersectRay(localRay,out float distance)&&distance>=0&&distance<=best){best=distance;aimedMachine=machine;}}
            foreach(var pile in Authority.World.piles){if(actor.pose.Distance(pile.pose)>12)continue;float height=.15f;foreach(long cell in pile.cells)height=Math.Max(height,cell/1000f);var bounds=new Bounds(Vector3.up*height*.5f,new Vector3(16,height,16));var rotation=Quaternion.Inverse(Rotation(pile.pose));var localRay=new Ray(rotation*(ray.origin-world.RenderBodyPosition(Body(pile.pose))),rotation*ray.direction);if(bounds.IntersectRay(localRay,out float distance)&&distance>=0&&distance<=best){best=distance;aimedMachine=null;aimedPile=pile;}}
        }
        public string InteractionPrompt=>MenuOpen||PlacementActive?"":aimedMachine!=null&&IsVehicle(aimedMachine)?"F - ENTER "+Nice(aimedMachine.definition).ToUpperInvariant()+" · Hold E for inventory / controls":aimedMachine!=null?"F - USE "+(aimedMachine.integratedLogistics?"MODULE LOGISTICS":Nice(aimedMachine.definition).ToUpperInvariant()):aimedPile!=null?"F - USE STOCKPILE":"";
        public bool InteractPlaced(){if(MenuOpen||PlacementActive)return false;FindAimedItem();if(aimedMachine==null&&aimedPile==null)return false;if(aimedMachine!=null&&IsVehicle(aimedMachine)){EnterVehicle(aimedMachine);return true;}contextIsPile=aimedPile!=null;contextTarget=contextIsPile?aimedPile.id:aimedMachine.id;selected=contextTarget;OpenMenu(contextIsPile?"pile":"machine");return true;}
        internal long VehicleMenuTarget(){if(Driving)return driver.id;if(MenuOpen||PlacementActive)return 0;FindAimedItem();return aimedMachine!=null&&IsVehicle(aimedMachine)?aimedMachine.id:0;}
        void UpdateToolkit(){
            if(uiRoot?.panel==null)return;bool visible=world.IsFirstPerson||world.IsDriving||Driving;uiRoot.style.display=visible&&!world.Paused?DisplayStyle.Flex:DisplayStyle.None;if(!visible){CloseMenu();return;}
            uiStatus.text=(Authority.World.creativeMode?"CREATIVE MODE · Free building/crafting/vehicle propulsion\n":"")+$"RADIATION {actor.dose:0.0}/100 · EXPOSURE {actor.exposure:0.00}/s"+(actor.craft==null?"":$"\nCrafting {Nice(actor.craft.recipe)} · {actor.craftQueue.Count} waiting");uiStatus.text+=WaterDirection()+TruckTracking()+(Driving?$"\nDRIVING {Nice(driver.definition)} · {driverMotor.ForwardSpeed*3.6f:0} km/h · {(Authority.World.creativeMode?"CREATIVE · FREE FUEL":"Fuel "+driver.input.Count("fuel"))}\n{driveBlockReason}":"");uiMessage.text=message;if(menuFeedback!=null)menuFeedback.text=message;uiPlacement.style.display=!MenuOpen&&!world.PersonalMenuOpen&&(world.RespawnPlacementActive||PlacementActive||world.BlueprintPlacementPrompt.Length>0)?DisplayStyle.Flex:DisplayStyle.None;uiPlacement.text=world.RespawnPlacementActive?world.RespawnPlacementPrompt:cableActive?cablePrompt:placementArmed?$"{(placingPile?"PAY-DIRT STOCKPILE":Nice(buildNames[palette]))} · {placementReason??"Ready"}\nLMB place · R rotate · Esc cancel":world.BlueprintPlacementPrompt;
            if(Time.unscaledTimeAsDouble>=nextAim){nextAim=Time.unscaledTimeAsDouble+.1;FindAimedItem();}uiPrompt.text=world.GroundLootPrompt.Length>0?world.GroundLootPrompt:Driving?"WASD drive · Space brake · Alt free look · F exit · Hold E for payload controls":InteractionPrompt.Length>0?InteractionPrompt:"F4 crafting · I inventory · G collect resources";
            int index=0;foreach(var deposit in Authority.World.deposits){if(deposit.pose.body!=world.definition.bodyId||actor.pose.Distance(deposit.pose)>60)continue;if(index>=depositLabels.Count){var label=UiText(uiRoot,"","industry-deposit");label.pickingMode=PickingMode.Ignore;depositLabels.Add(label);}var marker=depositLabels[index++];var point=world.View.WorldToScreenPoint(world.RenderBodyPosition(Body(deposit.pose)));marker.style.display=point.z>0&&!MenuOpen?DisplayStyle.Flex:DisplayStyle.None;var parentPoint=RuntimePanelUtils.ScreenToPanel(uiRoot.panel,new Vector2(point.x,Screen.height-point.y));marker.style.left=parentPoint.x;marker.style.top=parentPoint.y;marker.text=(deposit.remaining.radioactive>0?"RADIOACTIVE PAY DIRT":deposit.remaining.iron>0?"IRON PAY DIRT":deposit.remaining.copper>0?"COPPER PAY DIRT":Nice(deposit.resource).ToUpperInvariant())+ $"\n{deposit.remaining.litres:N0} L";}for(;index<depositLabels.Count;index++)depositLabels[index].style.display=DisplayStyle.None;
            if(Time.unscaledTimeAsDouble>=nextUiRefresh){nextUiRefresh=Time.unscaledTimeAsDouble+.2;RefreshToolkitMenu();if(!MenuOpen&&world.PersonalMenuOpen&&personalMaterials?.panel!=null)RefreshPersonalMaterials();}
        }
